program_text='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w-1):
            if grid[r][c] == bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0, h-1):
            if grid[r][c] == bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == bg:
                seen.add((nr,nc)); q.append((nr,nc))
    interior={(r,c) for r in range(h) for c in range(w) if grid[r][c] == bg and (r,c) not in seen}
    # Recolor any foreground cell that bridges two enclosed interior cells.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and ((r-1,c) in interior and (r+1,c) in interior or (r,c-1) in interior and (r,c+1) in interior):
                interior.add((r,c))
    out=[row[:] for row in grid]
    for r,c in interior:
        out[r][c]=4
    return out
'''
